// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 total, uint256 value) public {
        // Admissible domain: fund the contract with some total, withdraw 1..total of it.
        total = bound(total, 1, type(uint96).max);
        value = bound(value, 1, total);

        vm.deal(address(c), total);
        uint256 callerBefore = address(this).balance;

        // owner is the test contract (msg.sender at deployment), so call as owner.
        c.withdraw(value);

        // General rule: a successful withdraw(v) credits the recipient with EXACTLY v.
        assertTrue(address(this).balance - callerBefore == value);
    }

    receive() external payable {}
}
